companies = list_companies({})
first = boundary retry 2 {
    return list_contacts({ page: 1 })
} catch err {
    return fail("LIST_FAILED", err.code + ": " + err.message)
}
remaining = for page in list.range(2, first.total_pages + 1) {
    result = boundary retry 2 { return list_contacts({ page }) } catch err {
        return fail("LIST_FAILED", err.code + ": " + err.message)
    }
    return result.items
}
contacts = fold acc = first.items for page in remaining { return acc + page }

domain_to_company = fold acc = {} for c in companies {
    return acc + { [c.domain]: c.name }
}

is_digit = fun(ch) {
    return ch >= "0" and ch <= "9"
}

to_e164 = fun(phone) {
    chars = text.split(phone, "")
    digits = fold acc = "" for ch in chars {
        return acc + ch if ch >= "0" and ch <= "9" else acc
    }
    dlen = text.length(digits)
    normalized = if dlen == 11 and text.starts_with(digits, "1") {
        return "+" + digits
    } else if dlen == 10 {
        return "+1" + digits
    } else {
        return phone
    }
    return normalized
}

is_valid_e164 = fun(phone) {
    return regex.test(phone, "^\\+1[0-9]{10}$")
}

results = for contact in contacts {
    needs_phone = contact.phone != null and not is_valid_e164(contact.phone)
    new_phone = to_e164(contact.phone) if needs_phone else null
    phone_changed = needs_phone and new_phone != contact.phone and is_valid_e164(new_phone)

    email = contact.email if contact.email != null else ""
    parts = text.split(email, "@")
    domain = parts[1] if list.length(parts) == 2 else null
    needs_company = (contact.company == null or contact.company == "") and domain != null and domain in domain_to_company
    new_company = domain_to_company[domain] if needs_company else null

    updated = null
    if phone_changed and needs_company {
        updated = boundary retry 2 {
            return update_contact({ id: contact.id, phone: new_phone, company: new_company })
        } catch err {
            return fail("UPDATE_FAILED", err.code + ": " + err.message)
        }
    } else if phone_changed {
        updated = boundary retry 2 {
            return update_contact({ id: contact.id, phone: new_phone })
        } catch err {
            return fail("UPDATE_FAILED", err.code + ": " + err.message)
        }
    } else if needs_company {
        updated = boundary retry 2 {
            return update_contact({ id: contact.id, company: new_company })
        } catch err {
            return fail("UPDATE_FAILED", err.code + ": " + err.message)
        }
    }

    return {
        phone_fixed: phone_changed,
        company_filled: needs_company
    }
}

phones_fixed = fold acc = 0 for r in results {
    return acc + 1 if r.phone_fixed else acc
}
companies_filled = fold acc = 0 for r in results {
    return acc + 1 if r.company_filled else acc
}

submitted = submit_result({ answer: { phones_fixed: phones_fixed, companies_filled: companies_filled } })
return { phones_fixed, companies_filled, submitted }

